// src/data/catalog.ts
import { getVehicleImage } from './images';

export interface ChronicIssue {
  title: string;
  risk: string;
  desc: string;
  solution?: string;
}

export interface Motor {
  id: string;
  name: string;
  code: string;
  brands: string[];
  fuel: string;
  power: string;
  torque?: string; // Admin panelinden girilebilen opsiyonel tork bilgisi
  transmission: string;
  consumption?: string; // Admin panelinden girilebilen opsiyonel tüketim bilgisi
  score: number;
  risk: string;
  riskLevel: 'low' | 'medium' | 'high';
  note: string;
  pros: string[];
  cons: string[];
  chronic: ChronicIssue[];
  imageUrl?: string; // Dinamik görsel alanı eklendi
}

export interface Vehicle {
  id: string;
  name: string;
  brand: string;
  desc: string;
  score: number;
  engine: string;
  motorId: string;
  img: string;
  note: string;
}

